<template>
  <main class="exhibit-workbench">
    <template v-if="source">
      <ViewExhibition v-if="mode === 'exhibition'" ref="exhibition" :view="view" :sources="sources" :current-sources="sources" :initial-position="{ sectionIndex: 0, blockIndex: 1 }" showcase-linked @close="mode = 'article'" />
      <article v-else class="workbench-surface" :data-work="source.source_id">
        <ViewSourceBlock v-if="mode === 'article'" :source="source" :current-source="source" :block="block" />
        <ViewRichBlock v-else :block-id="source.source_id" :source="source" />
      </article>
    </template>
  </main>
</template>

<script>
import ViewExhibition from '../components/view/ViewExhibition.vue';
import ViewRichBlock from '../components/view/ViewRichBlock.vue';
import ViewSourceBlock from '../components/view/ViewSourceBlock.vue';
import { createViewCatalog } from '../utils/viewCatalog.js';
import { viewRichBlocks } from '../data/viewRichBlocks.js';
export default {
  name: 'ExhibitionWorkbench',
  components: { ViewExhibition, ViewRichBlock, ViewSourceBlock },
  data() { return { source: null, mode: this.$route.query.mode || 'component' }; },
  computed: {
    sources() { return new Map([[this.source.source_id, this.source]]); },
    block() { return { kind: 'source', source_id: this.source.source_id, presentation: this.source.presentations.includes('embed') ? 'embed' : 'interactive' }; },
    view() { return { title: this.source.title, question: this.source.title, summary: this.source.description, sections: [{ heading: this.source.title, introduction: this.source.description, blocks: [{ kind: 'bridge', text: this.source.description }, this.block] }] }; },
  },
  async mounted() {
    const index = await fetch('/assets/view-index.json').then(response => response.json());
    this.source = createViewCatalog({...index,rich_blocks:[...index.rich_blocks,...viewRichBlocks.filter(block=>block.retired)]}).find(source => source.source_id === this.$route.query.work);
  },
};
</script>

<style scoped>
.exhibit-workbench { position: fixed; inset: 0; z-index: 1000; overflow: auto; background: var(--site-bg-primary, #fff); }
.workbench-surface { width: 1100px; max-width: 100%; margin: 0 auto; padding: 28px; box-sizing: border-box; }
.workbench-surface :deep(.view-rich-block) { margin: 0; }
</style>
<style>
body:has(.exhibit-workbench) .header,
body:has(.exhibit-workbench) .back-to-top { display: none !important; }
</style>
